function daysSinceApril10() {
    const start = new Date(2026, 3, 10); // April 10, 2026

    const now = new Date();

    // Strip the time and normalize both dates to UTC
    const startUTC = Date.UTC(
        start.getFullYear(),
        start.getMonth(),
        start.getDate()
    );

    const nowUTC = Date.UTC(
        now.getFullYear(),
        now.getMonth(),
        now.getDate()
    );

    return (nowUTC - startUTC) / 86400000;
}

