if (!window.jsmediatags) {
    await new Promise((resolve, reject) => {
        const script = document.createElement('script');
        script.src = "https://cdnjs.cloudflare.com/ajax/libs/jsmediatags/3.9.5/jsmediatags.min.js";
        script.onload = resolve;
        script.onerror = reject;
        document.head.appendChild(script);
    });
}

// 3. Convert the Data URL to a Blob so the library can read it efficiently
const response = await fetch(audioSource);
const blob = await response.blob();

// 4. Extract the tags and format the output
return await new Promise((resolve) => {
    window.jsmediatags.read(blob, {
        onSuccess: function(tag) {
            const tags = tag.tags;

            // Set up the Array for the text data
            const title = tags.title || "Unknown Title";
            const artist = tags.artist || "Unknown Artist";
            const album = tags.album || "Unknown Album";
            const infoArray = [title, artist, album];

            // Set up the Data URL for the Cover Art
            let coverDataUrl = "";
            const image = tags.picture;
            if (image) {
                let base64String = "";
                for (let i = 0; i < image.data.length; i++) {
                    base64String += String.fromCharCode(image.data[i]);
                }
                coverDataUrl = "data:" + image.format + ";base64," + window.btoa(base64String);
            }

            // Return everything as a JSON string for PenguinMod to parse
            resolve(JSON.stringify({
                cover: coverDataUrl,
                info: infoArray
            }));
        },
        onError: function(error) {
            // Fallback if the file has no tags or fails
            resolve(JSON.stringify({
                cover: "",
                info: ["Unknown", "Unknown", "Unknown"]
            }));
        }
    });
});
